html:
{{ print_control(doc) }}
{%- macro v(value) -%}{{ (value or "") | e }}{%- endmacro -%}
{%- macro day(value) -%}{{ frappe.utils.format_date(value) if value else "" }}{%- endmacro -%}
{%- macro clock(value) -%}{{ frappe.utils.format_datetime(value, "dd-MM-yyyy HH:mm") if value else "" }}{%- endmacro -%}
{%- macro who(user) -%}{{ v(frappe.db.get_value("User", user, "full_name") if user else "") }}{%- endmacro -%}
{%- macro person(employee) -%}{{ v(frappe.db.get_value("Employee", employee, "employee_name") if employee else "") }}{%- endmacro -%}
{%- macro num(value) -%}{{ "{:g}".format(value | float) if value else "" }}{%- endmacro -%}
{%- macro zero(value) -%}{{ "{:g}".format((value or 0) | float) }}{%- endmacro -%}
{%- macro money(value) -%}{{ "{:,.0f}".format(value | float) if value else "" }}{%- endmacro -%}
{%- set logo = frappe.db.get_single_value("HRMS Addon Branding", "company_logo") -%}
<style>
.lpl-paper { font-family: Arial, Helvetica, sans-serif; font-size: 12px; color: #000; line-height: 1.5; }
.lpl-paper p { margin: 0 0 9px; }
.lpl-paper table { width: 100%; border-collapse: collapse; }
.lpl-paper tr { page-break-inside: avoid; }
.lpl-paper .ref { margin: 0 0 18px; }
.lpl-paper .ref td { border: 1px solid #000; padding: 5px 8px; vertical-align: middle; font-size: 11px; }
.lpl-paper .ref .co { text-align: center; font-size: 14px; font-weight: bold; }
.lpl-paper .ref .title { font-size: 12.5px; text-align: center; }
.lpl-paper .rows { margin: 0 0 14px; }
.lpl-paper .rows th, .lpl-paper .rows td { border: 1px solid #000; padding: 4px 7px; text-align: left;
  vertical-align: top; }
.lpl-paper .rows th { font-weight: bold; }
.lpl-paper .line { margin: 0 0 12px; }
.lpl-paper .fill { border-bottom: 1px dotted #000; display: inline-block; min-width: 110px; padding: 0 4px;
  min-height: 16px; vertical-align: bottom; }
.lpl-paper .w0 { min-width: 34px; }
.lpl-paper .w1 { min-width: 70px; }
.lpl-paper .w15 { min-width: 96px; }
.lpl-paper .w2 { min-width: 130px; }
.lpl-paper .w3 { min-width: 210px; }
.lpl-paper .w4 { min-width: 330px; }
.lpl-paper .box { border: 1px solid #000; min-height: 44px; padding: 5px 7px; margin: 0 0 14px;
  white-space: pre-wrap; }
.lpl-paper .sign { margin: 26px 0 14px; }
.lpl-paper .sign td { width: 50%; padding: 0 22px 0 0; vertical-align: top; border: none; }
.lpl-paper .sign .name { min-height: 18px; font-weight: bold; }
.lpl-paper .sign .rule { border-top: 1px solid #000; padding-top: 3px; }
.lpl-paper .said { font-style: italic; margin: 2px 0 0; }
.lpl-paper h4 { font-size: 12px; font-weight: bold; margin: 16px 0 9px; }
.lpl-paper .tick { display: inline-block; width: 28px; height: 19px; border: 1px solid #000; text-align: center;
  line-height: 19px; vertical-align: middle; margin: 0 8px 0 0; font-weight: bold; }
.lpl-paper .types td { border: none; padding: 3px 0; vertical-align: middle; }
.lpl-paper .state { font-weight: normal; }
/* A site's print styles pad every table cell (6px in Frappe's standard.css,
   10px in its Redesign style), grey and lighten every heading cell, and set
   the font on cells, divs and spans, all with !important or on the element
   itself. These say it again under .print-format, so the forms print as
   drawn whatever Print Style is chosen. */
.print-format .lpl-paper, .print-format .lpl-paper td, .print-format .lpl-paper th, .print-format .lpl-paper div,
.print-format .lpl-paper span, .print-format .lpl-paper p, .print-format .lpl-paper h4, .print-format .lpl-paper b {
  font-family: Arial, Helvetica, sans-serif !important; color: #000 !important; }
.print-format .lpl-paper td, .print-format .lpl-paper th { padding: 4px 7px !important; font-size: 12px;
  background-color: transparent !important; }
.print-format .lpl-paper th { font-weight: bold !important; }
.print-format .lpl-paper .rows th { border: 1px solid #000 !important; }
.print-format .lpl-paper .ref td { padding: 5px 8px !important; vertical-align: middle !important; font-size: 11px; }
.print-format .lpl-paper .ref td.co { font-size: 14px; }
.print-format .lpl-paper .ref td.title { font-size: 12.5px; }
.print-format .lpl-paper .sign td { padding: 0 22px 0 0 !important; }
.print-format .lpl-paper .types td { padding: 3px 0 !important; vertical-align: middle !important; }
.print-format .lpl-paper p.line { margin: 0 0 12px; }
</style>
{%- macro yes_no(answer, why=None) -%}
<p class="line"><span class="tick">{{ "&#10003;" if answer == "Yes" else "" }}</span>Yes &nbsp;
<span class="tick">{{ "&#10003;" if answer == "No" else "" }}</span>No</p>
{%- if why %}<div class="box">{{ v(why) }}</div>{% endif %}
{%- endmacro -%}
{%- macro answer(text) -%}<div class="box">{{ v(text) }}</div>{%- endmacro -%}
{%- set kinds = ["Resignation", "Termination", "Abscondment / Desertion", "Retirement", "Dismissal", "Others"] -%}
{%- set ticked = doc.custom_exit_kind -%}
<div class="lpl-paper">
<table class="ref">
<tr><td rowspan="2" style="width:24%">{% if logo %}<img src="{{ logo }}" style="max-height:46px">{% endif %}</td>
<td class="co">LUUKA PLASTICS LTD</td>
<td rowspan="2" style="width:27%">Reference: LPL/HR/10<br>Revision: 1<br>Issue Date: 14/03/2017<br>Revised: 10/04/2021</td></tr>
<tr><td class="title">Title: <b>EXIT INTERVIEW FORM</b></td></tr>
</table>
<p><b>Please note that your answers, comments and recommendations will be kept confidential and used for improving
the company's operations. Please give us your honest feedback.</b></p>
<table class="rows">
<tr><td style="width:50%"><b>Name:</b> {{ v(doc.employee_name) }}</td>
<td><b>Supervisor's Name &amp; Job Title:</b> {{ person(doc.reports_to) }}
{%- if doc.reports_to %} ({{ v(frappe.db.get_value("Employee", doc.reports_to, "designation")) }}){% endif %}</td></tr>
<tr><td><b>ID No.</b> {{ v(doc.employee) }}</td><td><b>Date of Joining:</b> {{ day(doc.date_of_joining) }}</td></tr>
<tr><td><b>Section/Department/Plant:</b> {{ v(doc.department) }}{% if doc.custom_branch %} / {{ v(doc.custom_branch) }}{% endif %}</td>
<td><b>Last Day of Work:</b> {{ day(doc.relieving_date) }}</td></tr>
</table>
<p class="line"><b>Type of separation or exit:</b></p>
<table class="types"><tr>
{%- for kind in kinds -%}
<td><span class="tick">{{ "&#10003;" if ticked == kind else "" }}</span>{{ kind }}
{%- if kind == "Others" and doc.custom_exit_kind_other %} ({{ v(doc.custom_exit_kind_other) }}){% endif %}</td>
{%- if loop.index == 3 %}</tr><tr>{% endif -%}
{%- endfor -%}
</tr></table>
<h4>1. What reasons motivated you to join the company?</h4>
{{ answer(doc.custom_joined_for) }}
<h4>2. What position(s) have you held since joining the company?</h4>
<table class="rows">
<tr><th>Designation / Job Title</th><th style="width:22%">From</th><th style="width:22%">To</th></tr>
{%- for row in doc.custom_positions_held or [] %}
<tr><td>{{ v(row.designation) }}</td><td>{{ day(row.from_date) }}</td><td>{{ day(row.to_date) }}</td></tr>
{%- else %}
<tr><td>&nbsp;</td><td></td><td></td></tr>
{%- endfor %}
</table>
<h4>3. Was your position in the Company what you expected it to be?</h4>
{{ yes_no(doc.custom_position_as_expected, doc.custom_position_not_why) }}
<h4>4. Were you given adequate training / clear job descriptions, roles and duties for you to succeed in your job?</h4>
{{ yes_no(doc.custom_training_adequate, doc.custom_training_not_why) }}
<h4>5. Briefly state your reasons for leaving the company.</h4>
{{ answer(doc.custom_leaving_reasons) }}
<h4>6. Do you feel that your Supervisor / Manager had realistic expectations about your performance, and discussed
with you in good time your performance expectations, plans, areas of improvement, training, coaching and mentoring?</h4>
{{ yes_no(doc.custom_supervisor_expectations, doc.custom_supervisor_advice) }}
<h4>7. What did you like most about working with Luuka Plastics Ltd?</h4>
{{ answer(doc.custom_liked_most) }}
<h4>8. What did you dislike about working with Luuka Plastics Ltd?</h4>
{{ answer(doc.custom_disliked_most) }}
<h4>9. Would you recommend Luuka Plastics to a friend as a place to work?</h4>
{{ yes_no(doc.custom_would_recommend, doc.custom_not_recommend_why) }}
<h4>11. Would you work for Luuka Plastics in future?</h4>
{{ yes_no(doc.custom_would_return, doc.custom_return_reason) }}
<h4>12. What areas would you recommend to management or the company for improvement?</h4>
{{ answer(doc.custom_improvements) }}
<h4>Signature Section</h4>
<table class="sign"><tr>
<td><div class="name">{{ v(doc.employee_name) }}</div>
<div class="rule">Employee{% if doc.custom_employee_signed_on %} &nbsp; {{ day(doc.custom_employee_signed_on) }}{% endif %}</div></td>
<td><div class="name">{{ who(doc.custom_supervisor_by) }}</div>
<div class="rule">Supervisor{% if doc.custom_supervisor_on %} &nbsp; {{ day(doc.custom_supervisor_on) }}{% endif %}</div>
{%- if doc.custom_supervisor_remarks %}<div class="said">{{ v(doc.custom_supervisor_remarks) }}</div>{% endif %}</td>
</tr><tr>
<td><div class="name">{{ who(doc.custom_hod_by) }}</div>
<div class="rule">Head of Department{% if doc.custom_hod_on %} &nbsp; {{ day(doc.custom_hod_on) }}{% endif %}</div>
{%- if doc.custom_hod_remarks %}<div class="said">{{ v(doc.custom_hod_remarks) }}</div>{% endif %}</td>
<td><div class="name">{{ who(doc.custom_hr_by) }}</div>
<div class="rule">HR Officer{% if doc.custom_hr_on %} &nbsp; {{ day(doc.custom_hr_on) }}{% endif %}</div>
{%- if doc.custom_hr_remarks %}<div class="said">{{ v(doc.custom_hr_remarks) }}</div>{% endif %}</td>
</tr></table>
</div>
